import crypto from 'crypto';
import { PrismaClient, HistFormat, HistResultType, HistMarginType, BowlingStyle } from '../index.js';
import {
  StatsContext,
  TeamFormResult,
  MatchFormSummary,
  HeadToHeadResult,
  H2HRecentMatch,
  TeamComparisonResult,
  SingleTeamMetrics,
  VenueStatsResult,
  PaceSpinResult,
  RecentAtVenueResult,
  RecentMatchSummary,
} from './types.js';

function createCacheKey(version: number, queryName: string, args: Record<string, any>): string {
  const sorted = JSON.stringify(args, Object.keys(args).sort());
  const hash = crypto.createHash('sha256').update(sorted).digest('hex').slice(0, 16);
  return `stats:v${version}:${queryName}:${hash}`;
}

async function runCached<T>(
  ctx: StatsContext,
  queryName: string,
  args: Record<string, any>,
  computeFn: () => Promise<T>
): Promise<T> {
  const version = ctx.statsVersion ?? 1;
  const key = createCacheKey(version, queryName, args);

  if (ctx.redis) {
    try {
      const cached = await ctx.redis.get(key);
      if (cached) {
        return JSON.parse(cached);
      }
    } catch {
      // Redis error fallback to DB
    }
  }

  const result = await computeFn();

  if (ctx.redis && result !== null && result !== undefined) {
    try {
      await ctx.redis.set(key, JSON.stringify(result), 'EX', 3600);
    } catch {
      // Redis set fallback
    }
  }

  return result;
}

function formatScoreDisplay(innings: any[]): string | null {
  if (!innings || innings.length === 0) return null;
  const inn = innings[0];
  return `${inn.runs}/${inn.wickets} (${inn.oversDisplay})`;
}

function formatMargin(
  resultType: HistResultType,
  winnerName: string | null,
  marginType: HistMarginType | null,
  marginValue: number | null,
  method: string | null
): string | null {
  if (resultType === HistResultType.TIE) {
    return winnerName ? `${winnerName} won via Super Over` : 'Match Tied';
  }
  if (resultType === HistResultType.DRAW) return 'Match Drawn';
  if (resultType === HistResultType.NO_RESULT) return 'No Result';

  if (!winnerName) return null;

  let text = '';
  if (marginType === HistMarginType.RUNS && marginValue !== null) {
    text = `${winnerName} won by ${marginValue} runs`;
  } else if (marginType === HistMarginType.WICKETS && marginValue !== null) {
    text = `${winnerName} won by ${marginValue} wickets`;
  } else {
    text = `${winnerName} won`;
  }

  if (method) {
    text += ` (${method})`;
  }
  return text;
}

/**
 * 1. getTeamForm: Last n finished matches for a team
 */
export async function getTeamForm(
  teamId: string,
  n = 5,
  ctx: StatsContext
): Promise<TeamFormResult> {
  return runCached(ctx, 'getTeamForm', { teamId, n, format: ctx.format, gender: ctx.gender }, async () => {
    const where: any = {
      OR: [{ teamAId: teamId }, { teamBId: teamId }],
      resultType: { in: [HistResultType.WIN, HistResultType.TIE, HistResultType.DRAW, HistResultType.NO_RESULT] },
    };

    if (ctx.format) where.format = ctx.format;
    if (ctx.gender) where.gender = ctx.gender;

    const matches = await ctx.prisma.histMatch.findMany({
      where,
      orderBy: { date: 'desc' },
      take: n,
      include: {
        teamA: true,
        teamB: true,
        winner: true,
        innings: {
          where: { isSuperOver: false },
        },
      },
    });

    const summaries: MatchFormSummary[] = matches.map((m) => {
      const isTeamA = m.teamAId === teamId;
      const vsTeamObj = isTeamA ? m.teamB : m.teamA;

      let result: 'W' | 'L' | 'T' | 'NR' = 'NR';
      if (m.resultType === HistResultType.WIN) {
        result = m.winnerId === teamId ? 'W' : 'L';
      } else if (m.resultType === HistResultType.TIE) {
        result = m.winnerId === teamId ? 'W' : (m.winnerId ? 'L' : 'T');
      } else if (m.resultType === HistResultType.DRAW || m.resultType === HistResultType.NO_RESULT) {
        result = 'NR';
      }

      const teamInnings = m.innings.find((inn) => inn.battingTeamId === teamId);
      const oppInnings = m.innings.find((inn) => inn.battingTeamId === vsTeamObj.id);

      return {
        matchId: m.id,
        cricsheetMatchId: m.cricsheetMatchId,
        date: m.date.toISOString().slice(0, 10),
        vsTeam: {
          id: vsTeamObj.id,
          name: vsTeamObj.name,
          code: vsTeamObj.code,
        },
        result,
        marginText: formatMargin(m.resultType, m.winner?.name || null, m.marginType, m.marginValue, m.method),
        teamRuns: teamInnings ? teamInnings.runs : null,
        opponentRuns: oppInnings ? oppInnings.runs : null,
      };
    });

    return {
      teamId,
      matches: summaries,
    };
  });
}

/**
 * 2. getHeadToHead: Head-to-Head statistics between two teams
 */
export async function getHeadToHead(
  teamAId: string,
  teamBId: string,
  n = 10,
  ctx: StatsContext & { venueId?: string }
): Promise<HeadToHeadResult | null> {
  return runCached(ctx, 'getHeadToHead', { teamAId, teamBId, n, venueId: ctx.venueId, format: ctx.format, gender: ctx.gender }, async () => {
    const where: any = {
      OR: [
        { teamAId, teamBId },
        { teamAId: teamBId, teamBId: teamAId },
      ],
      resultType: { in: [HistResultType.WIN, HistResultType.TIE, HistResultType.DRAW, HistResultType.NO_RESULT] },
    };

    if (ctx.venueId) where.venueId = ctx.venueId;
    if (ctx.format) where.format = ctx.format;
    if (ctx.gender) where.gender = ctx.gender;

    const matches = await ctx.prisma.histMatch.findMany({
      where,
      orderBy: { date: 'desc' },
      take: n,
      include: {
        teamA: true,
        teamB: true,
        winner: true,
        innings: {
          where: { isSuperOver: false },
        },
      },
    });

    if (matches.length < 2) {
      return null; // Insufficient sample
    }

    let teamAWins = 0;
    let teamBWins = 0;
    let ties = 0;
    let noResults = 0;

    const recentMatches: H2HRecentMatch[] = [];

    for (const m of matches) {
      if (m.resultType === HistResultType.WIN || (m.resultType === HistResultType.TIE && m.winnerId)) {
        if (m.winnerId === teamAId) teamAWins++;
        else if (m.winnerId === teamBId) teamBWins++;
      } else if (m.resultType === HistResultType.TIE) {
        ties++;
      } else {
        noResults++;
      }

      const innA = m.innings.filter((inn) => inn.battingTeamId === teamAId);
      const innB = m.innings.filter((inn) => inn.battingTeamId === teamBId);

      recentMatches.push({
        matchId: m.id,
        cricsheetMatchId: m.cricsheetMatchId,
        date: m.date.toISOString().slice(0, 10),
        format: m.format,
        winnerId: m.winnerId,
        winnerName: m.winner?.name || null,
        marginText: formatMargin(m.resultType, m.winner?.name || null, m.marginType, m.marginValue, m.method),
        teamAScore: formatScoreDisplay(innA),
        teamBScore: formatScoreDisplay(innB),
      });
    }

    return {
      totalMatches: matches.length,
      teamAWins,
      teamBWins,
      ties,
      noResults,
      recentMatches,
    };
  });
}

/**
 * 3. getTeamComparison: Compare win rates, batting 1st vs 2nd, highest/lowest scores
 */
export async function getTeamComparison(
  teamAId: string,
  teamBId: string,
  ctx: StatsContext,
  opts?: { venueId?: string }
): Promise<TeamComparisonResult> {
  return runCached(ctx, 'getTeamComparison', { teamAId, teamBId, venueId: opts?.venueId, format: ctx.format, gender: ctx.gender }, async () => {
    async function computeTeamMetrics(teamId: string, venueId?: string): Promise<SingleTeamMetrics> {
      const where: any = {
        OR: [{ teamAId: teamId }, { teamBId: teamId }],
        resultType: { in: [HistResultType.WIN, HistResultType.TIE, HistResultType.DRAW, HistResultType.NO_RESULT] },
      };
      if (venueId) where.venueId = venueId;
      if (ctx.format) where.format = ctx.format;
      if (ctx.gender) where.gender = ctx.gender;

      const team = await ctx.prisma.team.findUnique({ where: { id: teamId } });
      const teamName = team?.name || 'Unknown';

      const matches = await ctx.prisma.histMatch.findMany({
        where,
        orderBy: { date: 'desc' },
        take: 20,
        include: {
          innings: {
            where: { isSuperOver: false },
          },
        },
      });

      const matchesCount = matches.length;
      if (matchesCount === 0) {
        return {
          teamId,
          teamName,
          matchesCount: 0,
          winCount: 0,
          winPercentage: null,
          avgScoreBattingFirst: null,
          avgScoreBattingSecond: null,
          highestScore: null,
          lowestScore: null,
        };
      }

      const winCount = matches.filter((m) => m.winnerId === teamId).length;
      const winPercentage = matchesCount >= (venueId ? 3 : 5) ? Math.round((winCount / matchesCount) * 100) : null;

      const firstInningsScores: number[] = [];
      const secondInningsScores: number[] = [];
      const allScores: number[] = [];

      for (const m of matches) {
        // Exclude rain-reduced / DLS matches from run averages
        const isRainReduced = Boolean(m.method);
        const teamInnings = m.innings.find((inn) => inn.battingTeamId === teamId);
        if (!teamInnings) continue;

        allScores.push(teamInnings.runs);

        if (!isRainReduced) {
          if (teamInnings.inningsNumber === 1) {
            firstInningsScores.push(teamInnings.runs);
          } else if (teamInnings.inningsNumber === 2) {
            secondInningsScores.push(teamInnings.runs);
          }
        }
      }

      const avgScoreBattingFirst =
        firstInningsScores.length > 0
          ? Math.round(firstInningsScores.reduce((a, b) => a + b, 0) / firstInningsScores.length)
          : null;

      const avgScoreBattingSecond =
        secondInningsScores.length > 0
          ? Math.round(secondInningsScores.reduce((a, b) => a + b, 0) / secondInningsScores.length)
          : null;

      const highestScore = allScores.length > 0 ? Math.max(...allScores) : null;
      const lowestScore = allScores.length > 0 ? Math.min(...allScores) : null;

      return {
        teamId,
        teamName,
        matchesCount,
        winCount,
        winPercentage,
        avgScoreBattingFirst,
        avgScoreBattingSecond,
        highestScore,
        lowestScore,
      };
    }

    const teamAMetrics = await computeTeamMetrics(teamAId);
    const teamBMetrics = await computeTeamMetrics(teamBId);

    let venueComparison = null;
    if (opts?.venueId) {
      const vA = await computeTeamMetrics(teamAId, opts.venueId);
      const vB = await computeTeamMetrics(teamBId, opts.venueId);

      if (vA.matchesCount >= 3 || vB.matchesCount >= 3) {
        venueComparison = {
          venueId: opts.venueId,
          teamA: vA,
          teamB: vB,
        };
      }
    }

    return {
      sampleSizeA: teamAMetrics.matchesCount,
      sampleSizeB: teamBMetrics.matchesCount,
      teamA: teamAMetrics,
      teamB: teamBMetrics,
      venueComparison,
    };
  });
}

/**
 * 4. getVenueStats: Venue trends, batting first vs second, scores, toss impact
 */
export async function getVenueStats(
  venueId: string,
  ctx: StatsContext & { format?: HistFormat }
): Promise<VenueStatsResult | null> {
  return runCached(ctx, 'getVenueStats', { venueId, format: ctx.format, gender: ctx.gender }, async () => {
    const venue = await ctx.prisma.venue.findUnique({ where: { id: venueId } });
    if (!venue) return null;

    const where: any = {
      venueId,
      resultType: { in: [HistResultType.WIN, HistResultType.TIE, HistResultType.DRAW, HistResultType.NO_RESULT] },
    };
    if (ctx.format) where.format = ctx.format;
    if (ctx.gender) where.gender = ctx.gender;

    const matches = await ctx.prisma.histMatch.findMany({
      where,
      include: {
        innings: {
          where: { isSuperOver: false },
        },
      },
    });

    if (matches.length < 3) {
      return null; // Not enough data
    }

    let wonBattingFirst = 0;
    let wonBattingSecond = 0;
    let ties = 0;
    let noResults = 0;
    let tossWinnerWon = 0;
    let completedWithWinner = 0;

    const firstInningsScores: number[] = [];
    const secondInningsScores: number[] = [];
    let highestScoreChased: number | null = null;
    let lowestScoreDefended: number | null = null;

    for (const m of matches) {
      const inn1 = m.innings.find((inn) => inn.inningsNumber === 1);
      const inn2 = m.innings.find((inn) => inn.inningsNumber === 2);
      const isRainReduced = Boolean(m.method);

      if (m.resultType === HistResultType.WIN) {
        completedWithWinner++;
        if (m.tossWinnerId && m.tossWinnerId === m.winnerId) {
          tossWinnerWon++;
        }

        if (m.battingFirstTeamId && m.winnerId === m.battingFirstTeamId) {
          wonBattingFirst++;
          if (inn1 && !isRainReduced) {
            lowestScoreDefended =
              lowestScoreDefended === null ? inn1.runs : Math.min(lowestScoreDefended, inn1.runs);
          }
        } else if (m.battingFirstTeamId && m.winnerId !== m.battingFirstTeamId) {
          wonBattingSecond++;
          if (inn2 && !isRainReduced) {
            highestScoreChased =
              highestScoreChased === null ? inn2.runs : Math.max(highestScoreChased, inn2.runs);
          }
        }
      } else if (m.resultType === HistResultType.TIE) {
        ties++;
      } else {
        noResults++;
      }

      // Collect scores for completed, non-rain-reduced innings
      if (!isRainReduced) {
        if (inn1 && (inn1.balls >= 120 || inn1.wickets >= 10)) {
          firstInningsScores.push(inn1.runs);
        }
        if (inn2 && (inn2.balls >= 120 || inn2.wickets >= 10 || (m.winnerId && m.winnerId === inn2.battingTeamId))) {
          secondInningsScores.push(inn2.runs);
        }
      }
    }

    const totalMatches = matches.length;
    const winPctBattingFirst = totalMatches > 0 ? Math.round((wonBattingFirst / totalMatches) * 100) : 0;
    const winPctBattingSecond = totalMatches > 0 ? Math.round((wonBattingSecond / totalMatches) * 100) : 0;
    const tossImpactWinPct =
      completedWithWinner > 0 ? Math.round((tossWinnerWon / completedWithWinner) * 100) : null;

    const avgFirstInningsScore =
      firstInningsScores.length > 0
        ? Math.round(firstInningsScores.reduce((a, b) => a + b, 0) / firstInningsScores.length)
        : null;

    const avgSecondInningsScore =
      secondInningsScores.length > 0
        ? Math.round(secondInningsScores.reduce((a, b) => a + b, 0) / secondInningsScores.length)
        : null;

    return {
      venueId,
      venueName: venue.name,
      totalMatches,
      wonBattingFirst,
      wonBattingSecond,
      winPctBattingFirst,
      winPctBattingSecond,
      ties,
      noResults,
      avgFirstInningsScore,
      avgSecondInningsScore,
      highestScoreChased,
      lowestScoreDefended,
      tossImpactWinPct,
    };
  });
}

/**
 * 5. getPaceSpin: Breakdown of pace vs spin at venue over last n matches
 */
export async function getPaceSpin(
  venueId: string,
  n = 10,
  ctx: StatsContext
): Promise<PaceSpinResult> {
  return runCached(ctx, 'getPaceSpin', { venueId, n, format: ctx.format, gender: ctx.gender }, async () => {
    const where: any = { venueId };
    if (ctx.format) where.format = ctx.format;
    if (ctx.gender) where.gender = ctx.gender;

    const recentMatches = await ctx.prisma.histMatch.findMany({
      where,
      orderBy: { date: 'desc' },
      take: n,
      select: { id: true },
    });

    if (recentMatches.length === 0) {
      return { available: false, reason: 'no_wickets_recorded' };
    }

    const matchIds = recentMatches.map((m) => m.id);

    // Fetch bowler stats for these matches with player bowling style
    const bowlerStats = await ctx.prisma.histBowlerStat.findMany({
      where: { matchId: { in: matchIds } },
      include: {
        bowler: {
          select: { bowlingStyle: true },
        },
      },
    });

    let paceWickets = 0;
    let spinWickets = 0;
    let unclassifiedWickets = 0;

    let paceBalls = 0;
    let paceRuns = 0;
    let spinBalls = 0;
    let spinRuns = 0;

    for (const bs of bowlerStats) {
      const style = bs.bowler.bowlingStyle;
      if (style === BowlingStyle.PACE) {
        paceWickets += bs.wickets;
        paceBalls += bs.balls;
        paceRuns += bs.runsConceded;
      } else if (style === BowlingStyle.SPIN) {
        spinWickets += bs.wickets;
        spinBalls += bs.balls;
        spinRuns += bs.runsConceded;
      } else {
        unclassifiedWickets += bs.wickets;
      }
    }

    const totalWickets = paceWickets + spinWickets + unclassifiedWickets;
    if (totalWickets === 0) {
      return { available: false, reason: 'no_wickets_recorded' };
    }

    // Threshold check: >20% unclassified wickets => insufficient classification
    const unclassifiedRatio = unclassifiedWickets / totalWickets;
    if (unclassifiedRatio > 0.2) {
      return {
        available: false,
        reason: 'insufficient_bowler_classification',
        unclassifiedPct: Math.round(unclassifiedRatio * 100),
      };
    }

    const classifiedWickets = paceWickets + spinWickets;
    const paceWicketPct = classifiedWickets > 0 ? Math.round((paceWickets / classifiedWickets) * 100) : 0;
    const spinWicketPct = 100 - paceWicketPct;

    const paceOvers = paceBalls / 6;
    const spinOvers = spinBalls / 6;

    const paceEconomy = paceOvers > 0 ? Number((paceRuns / paceOvers).toFixed(2)) : null;
    const spinEconomy = spinOvers > 0 ? Number((spinRuns / spinOvers).toFixed(2)) : null;

    const paceAverage = paceWickets > 0 ? Number((paceRuns / paceWickets).toFixed(2)) : null;
    const spinAverage = spinWickets > 0 ? Number((spinRuns / spinWickets).toFixed(2)) : null;

    return {
      available: true,
      totalWickets,
      paceWickets,
      spinWickets,
      paceWicketPct,
      spinWicketPct,
      paceEconomy,
      spinEconomy,
      paceAverage,
      spinAverage,
      unclassifiedWickets,
    };
  });
}

/**
 * 6. getRecentAtVenue: Scorecards and results of last n matches at venue
 */
export async function getRecentAtVenue(
  venueId: string,
  n = 3,
  ctx: StatsContext
): Promise<RecentAtVenueResult> {
  return runCached(ctx, 'getRecentAtVenue', { venueId, n, format: ctx.format, gender: ctx.gender }, async () => {
    const where: any = { venueId };
    if (ctx.format) where.format = ctx.format;
    if (ctx.gender) where.gender = ctx.gender;

    const matches = await ctx.prisma.histMatch.findMany({
      where,
      orderBy: { date: 'desc' },
      take: n,
      include: {
        teamA: true,
        teamB: true,
        winner: true,
        innings: {
          where: { isSuperOver: false },
          orderBy: { inningsNumber: 'asc' },
        },
      },
    });

    const summaries: RecentMatchSummary[] = matches.map((m) => {
      const innA = m.innings.filter((inn) => inn.battingTeamId === m.teamAId);
      const innB = m.innings.filter((inn) => inn.battingTeamId === m.teamBId);

      return {
        matchId: m.id,
        cricsheetMatchId: m.cricsheetMatchId,
        date: m.date.toISOString().slice(0, 10),
        format: m.format,
        teamA: {
          id: m.teamA.id,
          name: m.teamA.name,
          code: m.teamA.code,
          score: formatScoreDisplay(innA),
        },
        teamB: {
          id: m.teamB.id,
          name: m.teamB.name,
          code: m.teamB.code,
          score: formatScoreDisplay(innB),
        },
        winnerName: m.winner?.name || null,
        marginText: formatMargin(m.resultType, m.winner?.name || null, m.marginType, m.marginValue, m.method),
      };
    });

    return {
      venueId,
      matches: summaries,
    };
  });
}
